    fun getSetupScript(token: String, port: Int): String {
        return """
#!/data/data/com.termux/files/usr/bin/bash
# ==========================================================
# JARVIS-HP Termux Agent Automated Installer
# Generated by JARVIS-HP Android Companion App
# ==========================================================

set -e
echo "=================================================="
echo "🤖 Installing JARVIS-HP Agent in Termux..."
echo "=================================================="

pkg update -y || true
pkg install -y python python-pip sqlite termux-api curl || true

PROJECT_DIR="${'$'}HOME/jarvis-hp"
mkdir -p "${'$'}PROJECT_DIR/tools/custom"
cd "${'$'}PROJECT_DIR"

echo "📥 Fetching agent components from local companion app..."
curl -s "http://127.0.0.1:$port/termux/agent.py" -o agent.py
curl -s "http://127.0.0.1:$port/termux/config.py" -o config.py
curl -s "http://127.0.0.1:$port/termux/memory.py" -o memory.py
curl -s "http://127.0.0.1:$port/termux/android_tools.py" -o tools/android_tools.py
curl -s "http://127.0.0.1:$port/termux/termux_tools.py" -o tools/termux_tools.py
curl -s "http://127.0.0.1:$port/termux/requirements.txt" -o requirements.txt

pip install -r requirements.txt || pip install requests

cat << 'EOF' > run.sh
#!/bin/bash
cd "${'$'}HOME/jarvis-hp"
python agent.py "$@"
EOF
chmod +x run.sh

echo "=================================================="
echo "✅ JARVIS-HP Agent installed successfully!"
echo "📁 Location: ${'$'}PROJECT_DIR"
echo "🔑 Local Token: $token"
echo "🚀 To run:"
echo "   cd ~/jarvis-hp"
echo "   python agent.py \"Buka YouTube dan cari Minecraft\""
echo "=================================================="
""".trimIndent()
    }

